package io.github.thomasfissh.androidgamepadbridge;
public class PadStateTest {
 static void ok(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args){PadState s=new PadState();s.key(96,true,"A");s.key(96,true,"A");ok(s.presses==1&&s.down(96),"held/repeat counting");s.key(96,false,"A");ok(!s.down(96),"release");s.motion(.75f,-.5f,-1,1,.25f,.8f,-1,1);ok(s.lx==.75f&&s.ly==-.5f&&s.rx==-1&&s.ry==1,"axis positions and direction preserved");s.analogLT=true;s.key(104,true,"L2");ok(s.leftTrigger(104)==.25f,"digital L2 must not replace actual analog travel");s.analogRT=false;s.key(105,true,"R2");ok(s.rightTrigger(105)==1,"digital trigger fallback");s.clearHistory();ok(s.lx==.75f&&s.down(104)&&s.presses==0,"clear statistics keeps current physical state");s.release();ok(s.held.isEmpty()&&s.lx==0&&s.rt==0,"focus loss releases stale display");s.motion(Float.NaN,Float.POSITIVE_INFINITY,2,-2,-1,2,3,-3);ok(s.lx==0&&s.ly==0&&s.rx==1&&s.ry==-1&&s.lt==0&&s.rt==1,"malformed axis safety");s.newDevice();ok(s.held.isEmpty()&&s.seen.isEmpty()&&s.motions==0&&!s.analogLT,"new or disconnected device resets state");System.out.println("PASS: key press/release, repeat, exact axes, analog/digital triggers, history reset, focus/disconnect and malformed inputs");}
}
